using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
public static class GridShiftV10Setup {
 [MenuItem("GridShift/10.0/Preparar campanha")]
 public static void Build(){var scene=SceneManager.GetSceneByPath("Assets/Scenes/SampleScene.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity",OpenSceneMode.Additive);try{var roots=scene.GetRootGameObjects();var manager=roots.SelectMany(r=>r.GetComponentsInChildren<DeliveryManager>(true)).First();var pedestrians=roots.SelectMany(r=>r.GetComponentsInChildren<PedestrianManager>(true)).First();var points=manager.points.Where(p=>p!=null&&p.Valid&&p.requiredExpansion==0).OrderBy(p=>p.id).ToArray();var pickup=points.First(p=>points.Any(d=>d!=p&&DeliveryRouting.Find(p.route,d.route)!=null));var destination=points.Where(d=>d!=pickup&&DeliveryRouting.Find(pickup.route,d.route)!=null).OrderBy(d=>DeliveryRouting.Find(pickup.route,d.route).Sum(DeliveryRouting.Length)).First();
 var target=pickup.establishment!=null?pickup.establishment.position:pickup.transform.position;Physics.SyncTransforms();var nodes=pedestrians.graph.nodes.Where(n=>!n.entrancePath&&n.neighbours.Length>0).OrderBy(n=>(n.position-target).sqrMagnitude).ToArray();Vector3 spawn=Vector3.zero;bool found=false;foreach(var n in nodes){if((n.position-target).sqrMagnitude>900)break;if(Physics.CheckCapsule(n.position+Vector3.up*.5f,n.position+Vector3.up*1.5f,.3f,~(1<<9),QueryTriggerInteraction.Ignore))continue;if(!Physics.Raycast(n.position+Vector3.up*.4f,Vector3.down,out var hit,1,~(1<<9),QueryTriggerInteraction.Ignore)||hit.normal.y<.9f)continue;spawn=hit.point;found=true;break;}if(!found)throw new Exception("Não foi encontrada uma posição livre e sustentada para o comerciante.");
 Directory.CreateDirectory("Assets/Generated/Campaign10");var model=(GameObject)PrefabUtility.InstantiatePrefab(pedestrians.models.First());model.name="CarlosMerchant";model.transform.position=spawn;foreach(var agent in model.GetComponentsInChildren<PedestrianAgent>(true))Object.DestroyImmediate(agent);foreach(var a in model.GetComponentsInChildren<Animator>())a.runtimeAnimatorController=pedestrians.controller;model.AddComponent<GridShiftMerchant>();var col=model.AddComponent<CapsuleCollider>();col.height=1.7f;col.radius=.28f;col.center=new Vector3(0,.85f,0);foreach(var t in model.GetComponentsInChildren<Transform>(true))t.gameObject.layer=9;var prefab=PrefabUtility.SaveAsPrefabAsset(model,"Assets/Generated/Campaign10/CarlosMerchant.prefab");Object.DestroyImmediate(model);
 var config=AssetDatabase.LoadAssetAtPath<GridShiftCampaignBalance>("Assets/Resources/GridShiftCampaignBalance.asset");if(config==null){config=ScriptableObject.CreateInstance<GridShiftCampaignBalance>();AssetDatabase.CreateAsset(config,"Assets/Resources/GridShiftCampaignBalance.asset");}config.merchantPrefab=prefab;config.merchantPoint=pickup.id;config.deliveryPoint=destination.id;config.merchantPosition=spawn;var forward=pickup.Stop-spawn;forward.y=0;config.merchantRotation=forward.sqrMagnitude>.01f?Quaternion.LookRotation(forward):Quaternion.identity;EditorUtility.SetDirty(config);AssetDatabase.SaveAssets();Directory.CreateDirectory("Docs/Validacao10");File.WriteAllText("Docs/Validacao10/setup.txt","Origem: "+pickup.id+" · "+pickup.displayName+"\nDestino: "+destination.id+" · "+destination.displayName+"\nCarlos: "+spawn+"\nPosição suportada e livre de colisões estáticas; rota dirigida existente.\nCenas preservadas; instalação pelos componentes existentes.\n");}finally{if(opened)EditorSceneManager.CloseScene(scene,true);}}
 public static void Batch(){Build();EditorApplication.Exit(0);}
}
